  VALUES 
    (664::BIGINT, 'El profe es bastante bueno y es súper buena persona, a mí me gustaban bastante sus clases, el problema viene en que no explicaba lo suficientemente claro para lo duro que calificaba. Además, sus proyectos son horribles y su asistente es demasiado malo para calificar y todo lo califica él.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'f639457e10a4eb6a8f1b3468e283ab0973a37ef349e3c7fbeb22575e2f895bac'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Que alguien le diga que se actualice? que Odoo ya no se usa...'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '208870c2745fbd3f739fd6895c459e01ee78bed3e784509579c16ff039c50d5f'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'El profe sabe del tema, pero en las clases solo se dedica a leer diapositivas, las prácticas no existen, solo manda tareas que revisan los asistentes y por cualquier cosa bajan puntos, los examenes son muy largos y cualquier cosa le quita muchos puntos, es solo ponerle ganas y estar atento'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '875891a454426f244be8d5c2a300bfbc10126e84608efbd188d876d00efa7649'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Digamos, la parte de contabilidad y cómo hacerla, todo bien, ngl, pero la parte del proyecto ese (...). Es un buen profe, se termina en semana 16-17, va muy al dia. Tiene buenos asistentes. Solo voy a decir que el curso de la nada paso de ser anual a semestral, por tu ya sabes quién.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'a5f777f357e6deed2b142f07cfe8ccd40bc90067c4b731d24b437a125f96b527'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'De momento es el mejor profe con el que e llevado, demasiado claro, el tiene su metodologia de aprendizaje bien clarita, lo que hace que uno la comprenda de manera mas sencilla, y ni mencionar el amplio conocimiento que tiene, y la calidad de persona que es!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9fe68c2b3447d60947b84e7c74eb7eef488d0c1e269d96aa99ae21650f3049d5'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Es de los mejores profes que he tenido, su metodo de explicar es el mejor, las tareas que ponga haganlas, a base de hacer tarea se pasa el curso ya que uno aprende todo lo necesario realizando sus tareas, un profe super buena gente y clases amigables y divertidas, vayan a clase y pasan seguro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a6e943aa2f3a0095f2efb9a5291521d97c734cc89d64df0a0b78df91978b7696'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'El profe sabe mucho del tema, además está dispuesto a explicar las veces que sea necesario para que el estudiante entienda. En general el profe es muy buena gente, llevaría más cursos con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, '065765826895b4a489f4fdfe27ad2b685c081b0f743f6bc3580eccbd84ddf052'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Muy buen profe, sus clases son muy buenas y se toma el tiempo de que sus estudiantes aprendan y entiendan bien. Es muy buena gente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'f261a3d262fe7dc64b58447c8bdcb8eff79339ac694b8782843abcb264b4822d'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Es el mejor profe de ATI sin duda alguna.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-17T00:00:00+00:00'::TIMESTAMPTZ, '735449e52a9e72e45cfad0bee0a75eb40e357719ad7e41ff67e97770ba29990f'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'Por mucho se nota que sabe lo que hace. El mejor profe de conta que puede haber, llevaría su clase de nuevo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'adcdc959ec25516fc1580f3d35d0fce70cdc6d4a6a388b81ac66cd668ddf03fe'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Gabriel es el mejor, es excelente profe excelente persona y sabe un montón (AMA a Odoo, pero también sabe un montón de otras cosas). Sí, las presentaciones son feas pero el curso es bonito y créame que es excelente en lo que hace. Matriculen con él si tiene el chance, full recomendado ;)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '4b2435990f4965c0981b029ce3dd1354bb9121390b0416d4299a834cbcb0ac95'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'Facil el mejor curso de la carrera, si tienen la oportunidad de escoger esta electiva, se las recomiendo. Muy util para la vida laboral y en general para ser ATI. El profe es excelente, deberían darle más crédito.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'bf2fcf138ec168c9cea30d9b02c87cddbd6481959159021d2c4f9d90fdc80e4b'::TEXT, ARRAY[2569]::BIGINT[]),
    (664::BIGINT, 'Uno de los mejores profesores de ATI, las clases son muy buenas y se asegura de que todos avancemos al mismo ritmo en Odoo. Da retroalimentación constructiva y siempre responde a las preguntas de manera positiva ????'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c0d2ee9cbe7009f2c0e3875931138ed37d083dc1c4f615ce87f89b3aed0de59d'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'El profe Gabriel es una excelente persona, le puedo decir que es la luz en el cielo oscuro. El se caracteriza por la amabilidad y pasion con la que da el curso de transformacion digital, ademas de ser una electiva nueva es super completa y en constante evolucion todo ATI debe cursar, vale la pena'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'f32f8f0c3d5198bd6d02268c4367610409642cccb2f1d48cfc41733fe6c6969f'::TEXT, ARRAY[2569]::BIGINT[]),
    (664::BIGINT, 'Explica todo muy bien, siempre está atento a que todos los estudiantes estén entendiendo. Hay que asistir a las clases porque toma en cuenta el trabajo en clase para la calificación. Muy amable y anuente a ayudar siempre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-24T00:00:00+00:00'::TIMESTAMPTZ, '252b2296cced0254caab6889802ef5b8cc0354894c28182152a56ce8be1017ef'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'Es muy buen profe, a veces califica medio duro pero se aprende muchísimo con él y es bastante bueno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'b5082077138f6658ee0b9beb7d12eb00b0e3ea32232c0303c74609c9dd134494'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '3290f536cd27ba0a127a9b608c99d576a8fb299ef08198cd4ece8a9c5331d514'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'El profe explica muy bien y los exámenes no son tan complejos'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e8e5ecec0f4b168fb32504700f7393afc847a25e1da54d6e933a5dc7b64e6149'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'El profe es buena gente, pero siento que explica muy por encima en algunas ocasiones. Califica medio duro, pero los exámenes no estaban tan complicados.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'a486d77d17b094c62a3d0d83449cf11648e7ecb446a95322f51fa9c5ff348222'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Es un muy buen profe, explica muy bien, sin embargo califica duro, metan el curso con él si pueden, se aprende mucho.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-06-07T00:00:00+00:00'::TIMESTAMPTZ, '04bfe295730822d32ade993581be884a84a4886b9f9cdbf332c26efa7c23755e'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Muy buen Profe, explica claro y la manera que da las clases hace que no sea aburridas. Sin pensarlo matricularía con el de nuevo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '2e5293b6a6131bd905ae0a05a4b25fa302b516b946897b70e25e833fb323c165'::TEXT, ARRAY[2449]::BIGINT[]),
    (664::BIGINT, 'Es muy buen profe, se preocupa porque los estudiantes aprendan. Explica bastante claro y deja trabajos de todos los temas vistos en clase lo que ayuda a practicar y reforzar la materia vista. Los exámenes son iguales a lo visto en las prácticas y tareas, pero la teoría también entra.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '807cdd225309d9b6c81dd8e8291e0a7ac83a85020529c782a3943ddc0b3282cc'::TEXT, ARRAY[2449]::BIGINT[]),
    (664::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'd4a8c1f6ca0020873bf7a5a7b06ae7fad12cf7fb12006c669307c26a7d778477'::TEXT, ARRAY[2449]::BIGINT[]),
    (664::BIGINT, 'El curso demanda bastante tiempo, pero el profesor explica muy bien.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'cbeddbe223415f663c6bd792e051249de019626c0df0879cf7d9ede40cc08cb6'::TEXT, ARRAY[2449]::BIGINT[]),
    (664::BIGINT, 'Muy buen curso y explica bastante bien, por lo general prefiere las clases presenciales pero algunas son asincrónicas. Muy organizado, volvería a tomar un curso con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '7ad9339c8b4cf1df8a83edfe11eed1be221996f14862aec9e5abf8b468918a10'::TEXT, ARRAY[2449]::BIGINT[]),
    (664::BIGINT, 'Super buen profe, es demasiado respetuoso y excelente profesional! No dude en llevar clase con el, la electiva de transformacion digital 10/10. se aprende mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-05-29T00:00:00+00:00'::TIMESTAMPTZ, '129b14c6c57b6f4781f8611925588b23fc29501f1b7615d428c5f684b3704763'::TEXT, ARRAY[2569]::BIGINT[]),
    (664::BIGINT, 'De lo mejor que tiene ATI, el profe es muy sencillo al momento de dar sus clases, y se le entiende perfectamente lo que nos quiere transmitir, conecta muy bien con los estudiantes lo que hace que las clases sean amenas y muy provechas. Súper recomendado, además que se nota que le gusta el tema 10/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-05-21T00:00:00+00:00'::TIMESTAMPTZ, '7b2d7fd5d610685a46365bfb7816922ab92c2e4765c72731b9b017d5f7153e3a'::TEXT, ARRAY[2569]::BIGINT[]),
    (664::BIGINT, 'Es un excelente profesor, explica y se preocupa por que uno entienda, lo unico es que si debe de poner de su parte, participar y preguntar para sacar mejor provecho de la clase. Las clases las intenta hacer dinamicas y cortas. Buen curso para aterrizar conceptos vistos en la carrera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-05-21T00:00:00+00:00'::TIMESTAMPTZ, '84d26c7b470e7dc6253ae4eabc4b9ff533b9cc009161dae266aa22d6a2143bce'::TEXT, ARRAY[2569]::BIGINT[]),
    (664::BIGINT, 'Muy buen profe, se nota que le apasiona lo que hace, tiene demasiado conocimiento de todos los temas que trata. Las evaluaciones son sencillas y se enfocan en que uno aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'd85eb2ff8440d3e4fde933e6d36d1b2e87f1d416618e5fc782b7cfce5ee4e39f'::TEXT, ARRAY[2569]::BIGINT[]),
    (664::BIGINT, 'Un excelente profesor, pero tienes que estar muy enfocado en la clase porque si no te va a ir pésimo en los exámenes.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-04-26T00:00:00+00:00'::TIMESTAMPTZ, 'f436ce7e2a191a5608e98080309d6f41079242c554ea7c17a2942ae54b0c17d3'::TEXT, ARRAY[2507]::BIGINT[]),
    (664::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria']::TEXT[], '2024-03-30T00:00:00+00:00'::TIMESTAMPTZ, 'a56317b958edf967434771a1a76d7730f6e45cc6a344199c9b2cd330aac226ec'::TEXT, ARRAY[2578]::BIGINT[]),
    (664::BIGINT, 'Sin duda volvería a matricular con él si podría es excelente explicando y se centra en que aprenda en proyectos buenos e interesantes y no aplica exámenes es lo mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-12-19T00:00:00+00:00'::TIMESTAMPTZ, '268d2138e7f6a08b3c4e62ecd4e3d26d16e890d1967114f6a6ac584aa48a8b53'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'Uno de los mejores profesores de la carrera (o el mejor directamente), no hace exámenes y se centra en proyectos con exposiciones grupales (grupos escogidos por los estudiantes), da mucha retroalimentación y de verdad se entienden las clases. Matriculen con él sin ninguna duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'c90ab460c11dd92dd891eed95dd41c8eaa85566dc5bbe3d150f6bc3df10b3c3b'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'El curso es muy fácil, algunos trabajos se hacen en clase y los trabajos grandes no requieren de muchísimo tiempo. La mayoría de los temas son aburridos pero sencillos. El profe es muy buena gente, pero siento que a veces se toma las cosas personales. Siga las instrucciones que sube y pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '30085f2921fed34b47c36e75e7ce0f3a73d54dbecf0a7c59cfbba779a7c78cd9'::TEXT, ARRAY[2569]::BIGINT[]),
    (664::BIGINT, 'De los mejores profes que me he topado en la carrera. Las clases están muy enfocadas en búsqueda de la preparación académica profesional y los ejemplos de clase muy acertados con la materia. Además incluyó muchos laboratorios que facilitaron la comprensión del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '10e91c433dbed4c57203c9d9d23301f65a8efd4a6fab577209bfde335ecb857e'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'Califica muy rudo, los examenes son muy rudos, sin embargo, el profe se esfuerza en las clases y procura que los estudiantes entiendan, da buenos recesos, y las lecturas y casos ayudaron a que no se perdieran tantos puntos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '9d73654ba134500fecbbf350a67c947b993e3b04276d54eaf685a5ecbb9102c8'::TEXT, ARRAY[2520]::BIGINT[]),
    (664::BIGINT, 'Muy buen profesional, pero como profe puede que le falte experiencia. El proyecto fue un poco abusado debido a todo lo que requería, pero él ayuda bastante con el tiempo. Los exámenes otro nivel de dificultad, casi nadie los pasa, por lo cual es importante esforzarse bastante con tareas y demás.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '7319e1de05d5cedadac5c66526dbf7e58c607723397b45b1842aaddbe5d94826'::TEXT, ARRAY[2520]::BIGINT[]),
    (664::BIGINT, 'Siento que le hace falta un poco de orden a sus clases, se vio que varios materiales de él ocupaban revisión, si hubo bastante tareas y lecturas pero eso se espera del tec.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'dbfdda2557804fba7893a9468c9e04bab634c2dfc2247a3750a5c5adac67ab77'::TEXT, ARRAY[2520]::BIGINT[]),
    (664::BIGINT, 'Se nota su interés por lo que explica dado que es con lo que se gana la vida. Si es importante saber que los trabajos son constantes todas las semanas sin excepción, en especial casos grupal y lecturas con formatos muy específicos. Es muy empático a la hora de deadlines. Muy buen profe!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '7198ad858d700bd1c4a2cb561bf0b1540809f241cd0d651722140def9a77a89f'::TEXT, ARRAY[87, 2520]::BIGINT[]),
    (664::BIGINT, 'Es un muy buen profe, sabe y ayuda bastante, quizá las evaluaciones son un poco fuertes pero, es lo que se necesita para preparase para siguientes cursos (AP 1 y 2)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '9cb458bc01e380df8d3f9372dd5f17f0466a4bb6c336ac684e1d78e797375b2d'::TEXT, ARRAY[2520]::BIGINT[]),
    (664::BIGINT, 'Deja mucho que desear como profesor, sinceramente NO lo recomiendo, un curso de 3 créditos, sentí que valía 5 créditos, demasiados casos y lecturas que quitan tiempo valioso, aparte califica asqueroso, aunque uno se esfuerce. No sabe explicar y tampoco tiene orden.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '288030a607173aaf3b4cb942111c076d8da0cf0eb16a8233a4504cfc6eb89eef'::TEXT, ARRAY[87, 2520]::BIGINT[]),
    (664::BIGINT, 'Es una muy buena persona, se preocupa mucho por sus estudiantes y es muy amable. Sin embargo le falta mucho orden. Algunas veces explica algo y lo califica de forma muy distinta. Debería de revisar mejor las especificaciones y documentos para los trabajos. Cmo persona 10/10, como profesor 6/10.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Deja trabajos largos']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'd10f1a968b205847a390848120a56f80c14314ff588b948d5be50f4cc2c5baf7'::TEXT, ARRAY[2520]::BIGINT[]),
    (664::BIGINT, 'Gabriel es de lo mejor que tiene ATI, tanto en la parte profesional como en la personal, ya que es un profe que siempre está dispuesto a ayudar, es carismático, simpático y comprensible. Además, la forma en que motiva a sus estudiantes es excepcional. No dude en matricular con él. Sus clases 10/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-11-17T00:00:00+00:00'::TIMESTAMPTZ, '5d235af99a1630bdfa2a761450fe8de819e2e96d2d749d5f7980505473c3bc6a'::TEXT, ARRAY[87, 2520]::BIGINT[]),
    (664::BIGINT, 'La mejor clase, en ocaciones el proceso universiatrio es muuy burocrático y este profe hace cosas distintas, me daba alegría ir a sus clases y aprendi mucho :)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'ad2af38afa122d788480602d0d6f836669513a51f153c0439d0b457c001ef1c0'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'El profe es muy agradable, está dando constante reroalimentación a todos sus estudientes. Asigana sufucientes trabajos para una comprención escalonada de los contenidos del curso (No satura de trabajos).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2022-11-11T00:00:00+00:00'::TIMESTAMPTZ, '51c6896ae24caf97f9967c28deaa5797ee07ba14823c07ed56373f071c422c1c'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'Es uno de los mejores profes que he tenido, si es bastante exigente con trabajos bien hechos y demás, pero es la persona indicada si usted quiere aprender, además es muy pura vida'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-09T00:00:00+00:00'::TIMESTAMPTZ, '05f54810c3275c52977559d980b295234379fb7c7e9a49b8c2815291bfcb262f'::TEXT, ARRAY[87, 2520]::BIGINT[]),
    (664::BIGINT, 'Es un excelente ser humano y profesor, recibí 2 cursos con él y en los 2 quedé completamente satisfecho, tuve una situación personal y no podía entregar mi proyecto final a tiempo y él la comprendió completamente y me brindó ayuda, además hoy en día trabajo y aun le pido consejos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-07T00:00:00+00:00'::TIMESTAMPTZ, '9cc9661704fdc223c8e76828a4b557e58c3d61357845d6421ec0dbfa064cb36d'::TEXT, ARRAY[2579]::BIGINT[]),
    (664::BIGINT, 'El profe Gabriel es de los más carismáticos de ATI (Tipo Néstor). Muy tuanis en las clases y bastante comprensivo con la situación del estudiante. Siempre se preocupa por generarle un valor agregado al estudiante como profesional. Más que recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-06T00:00:00+00:00'::TIMESTAMPTZ, 'fc61952e9f992a24435be9a728963cfafc7b9d6422d8675fedb5bc80c57d5779'::TEXT, ARRAY[2588]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
